import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 69 · Christmas recipe: no-bake rum balls and bourbon balls (Google Trends 3/11: easy christmas cookie recipes, christmas treat recipes rising)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, every Christmas cookie tray in my family had a little secret hiding in the corner. A plate of small, dark, sugar-dusted balls that looked innocent as could be. The children always grabbed one first. And then they made a terrible face, because those were Aunt Margaret's rum balls, and they had enough rum in them to make a sailor blush.""",
   "rum balls powdered sugar plate", "TO MAKE A SAILOR BLUSH")
sc("""Rum balls are the easiest Christmas treat there is. No baking, no oven, five ingredients, twenty minutes. But people tell me theirs are dry and crumbly, or too wet to roll, or they taste like nothing but alcohol. So tonight I'm giving you Aunt Margaret's rum balls, and the five mistakes that ruin them. And stay with me, because the last secret is about waiting, and it's what makes them taste like a fancy bakery.""",
   "dry crumbly cookie balls", "NO BAKING AT ALL")

ch("Aunt Margaret's tin")
sc("""Aunt Margaret lived in Columbus, and every December she arrived at our house with a big round tin painted with snowmen. Inside, on wax paper, were exactly sixty rum balls. She counted them. She said, Dorothy, I counted them in Columbus, so I'll know if Walter eats any before Christmas. My father always ate four, and she always knew.""",
   "vintage snowman cookie tin", "SHE COUNTED THEM")
sc("""Rum balls came to America from Europe, honey, where people made little balls of crumbs, nuts, cocoa and rum to use up the stale cake and cookies after the holidays. Nothing went to waste. In the nineteen fifties and sixties, every church cookbook in America had them, made with vanilla wafers. In a minute I'll tell you which cookie makes the best ones.""",
   "1950s church cookbook recipe page", "NOTHING WENT TO WASTE")
sc("""And they're perfect for busy people, sweetheart. You can make them two weeks ahead, and they get better every single day. If you have twenty minutes and a bowl, you can have a whole tin of Christmas candy for your neighbors, your office, or your church party, for about eight dollars.""",
   "tin of homemade Christmas treats", "TWENTY MINUTES AND A BOWL")

sc("""One year, honey, in nineteen fifty-nine, Aunt Margaret's tin got mixed up with my mother's tin of chocolate drop cookies on the church Christmas table. The minister's wife ate three of Aunt Margaret's, thinking they were the chocolate drops. She led the closing hymn with more feeling than anybody had ever heard in that church. Aunt Margaret never said a word. She just smiled into her hymnal.""",
   "church Christmas party hymn singing", "MORE FEELING THAN EVER")

ch("What you need")
sc("""Here's what you need for about four dozen. Two and a half cups of finely crushed vanilla wafers, about one box. One cup of powdered sugar, plus more for rolling. One cup of pecans or walnuts, chopped very fine. Two tablespoons of unsweetened cocoa powder. Three tablespoons of light corn syrup or honey. And half a cup of dark rum.""",
   "vanilla wafers pecans cocoa rum", "THE INGREDIENTS")
sc("""And here's mistake number one. Using white rum. White rum tastes sharp and hot, like rubbing alcohol. Dark rum tastes warm and rich, like molasses and vanilla. Or use bourbon, and call them bourbon balls, which is how they make them in Kentucky. My Aunt Louise in Kentucky made bourbon balls, and Aunt Margaret in Ohio made rum balls, and they argued about it for forty years.""",
   "dark rum bourbon bottles", "DARK RUM, NOT WHITE")
sc("""And for the children, or anybody who doesn't drink, use orange juice or apple juice with a teaspoon of rum extract or vanilla instead of the rum. They're just as good, honey. I make one tin of each, and I put a red ribbon on the grown-up tin, so nobody mixes them up. You'll remember that from the eggnog.""",
   "orange juice vanilla extract bottle", "ONE TIN OF EACH")

ch("The crumbs")
sc("""Step one. Crush the vanilla wafers into very fine crumbs. A food processor is easiest. Or put them in a big zipper bag and roll over them with a rolling pin, which is how Aunt Margaret did it, and it's good for your temper. Mistake number two is big crumbs. Lumpy crumbs make lumpy rum balls that fall apart. You want them as fine as sand.""",
   "crushing cookies rolling pin bag", "AS FINE AS SAND")
sc("""And toast the nuts first, sweetheart, five or six minutes at three fifty, until they smell warm. Then chop them very, very fine, almost as fine as the crumbs. Toasted nuts taste rich and buttery. Raw nuts taste flat. And fine nuts help hold the balls together. Big chunks of nut make them crack when you roll them.""",
   "finely chopped toasted pecans", "CHOP THEM FINE")

ch("Mixing")
sc("""Step two. In a big bowl, stir together the crumbs, the powdered sugar, the nuts and the cocoa, until it's all one even color. Then add the corn syrup and the rum, and stir it with a wooden spoon, and then with your hands, until it comes together like a soft dough. It should hold together when you squeeze a little in your palm.""",
   "mixing crumb dough hands bowl", "SQUEEZE TEST")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Now, mistake number three. Getting the texture wrong. If it's too dry and crumbly, add a little more rum or a spoon of corn syrup. If it's too wet and sticky, add more crumbs. Every box of cookies is different. Add a little at a time, until it rolls smooth like play dough.""",
   "adjusting dough texture spoon", "LIKE PLAY DOUGH")

sc("""And here's a tip from Aunt Margaret for a richer rum ball. Melt two ounces of dark chocolate and stir it into the mixture with the rum. It makes them taste like a real chocolate truffle, and it helps hold them together. She only did it for the Christmas Eve tin, the special one. The ordinary rum balls were for the neighbors.""",
   "melted dark chocolate bowl", "THE CHRISTMAS EVE TIN")

ch("Rolling")
sc("""Step three. Roll the mixture into small balls, about one inch across, the size of a big marble. Keep them small, honey. Mistake number four is big rum balls. They're rich and strong, so a small one is plenty. A big one is too much rum in one bite. Aunt Margaret made hers exactly the size of a walnut, and she checked them against a real walnut.""",
   "rolling small rum balls hands", "THE SIZE OF A WALNUT")
sc("""Roll each ball in powdered sugar, or in cocoa powder, or in finely chopped nuts, or in colored sprinkles for Christmas. I like to do a mix of all of them, so the tray looks pretty. Or dip them halfway in melted chocolate. Then set them on a tray lined with wax paper. Wet your hands a little if the mixture sticks.""",
   "rum balls rolled sugar cocoa nuts", "ROLL THEM PRETTY")
sc("""So far, dark rum or bourbon, very fine crumbs, toasted fine nuts, the right texture, and small balls rolled in sugar. And now the secret I promised, Aunt Margaret's secret. Mistake number five is eating them right away. Fresh rum balls taste raw and boozy, like the rum is sitting on top of a cookie. They need time.""",
   "tray of fresh rum balls", "THEY NEED TIME")

ch("The waiting")
sc("""Put them in an airtight tin, in layers with wax paper between them, and let them sit in a cool place for at least three days, and a week is even better. The rum soaks into the crumbs and mellows, and the flavors blend together until they taste rich and smooth, like a fancy chocolate truffle from a bakery. That's why Aunt Margaret made hers the first week of December.""",
   "airtight tin layers wax paper", "LET THEM REST")
sc("""Before serving, roll the powdered sugar ones in a little more sugar, because the first coat soaks in. And they keep for three or four weeks in a tin, in a cool place, and they freeze for three months. They're the perfect thing to make on the first cold weekend of December, and then forget about until the party.""",
   "rolling rum balls fresh sugar", "A FRESH COAT")

ch("Variations")
sc("""Once you know how, you can make them any way you like, sweetheart. Use chocolate wafer cookies instead of vanilla, for a darker ball. Use gingersnaps, with a little cinnamon and rum, for a spicy one. Use crushed graham crackers and orange juice, with orange zest, for the children. Or leftover fruitcake, which is what the old Europeans did, and it finally gives fruitcake a purpose.""",
   "gingersnaps chocolate wafers variations", "A PURPOSE FOR FRUITCAKE")
sc("""And here's a little shortcut. Some people use leftover brownies or chocolate cake instead of cookie crumbs, crumbled up with a little frosting and rum. My granddaughter calls them drunk brownie bites. That's not what we called anything in nineteen fifty-five, but I have to admit they're delicious.""",
   "brownie crumbs balls chocolate", "BROWNIE BITES")

sc("""And a word of caution, sweetheart, because it matters. These rum balls aren't cooked, so the alcohol stays in them. Keep them away from children, from anybody who doesn't drink, from anybody who's driving, and from anybody expecting a baby. Label the tin. And never leave a plate out where little hands can reach it. Make the juice version for them. They'll love it just as much.""",
   "labeled tin grown-ups only", "LABEL THE TIN")

ch("Giving")
sc("""Rum balls make a beautiful gift, honey. Put them in little paper candy cups in a tin or a box, with a tag that says made with rum, so nobody's surprised. They travel well, they don't melt, and they don't break. I mail a box to my son in Arizona every year, next to the toffee. And always tell people they're grown-up treats, especially if there are children around.""",
   "rum balls gift box paper cups", "A GROWN-UP GIFT")

ch("Grandma's kitchen")
sc("""So one more time. Dark rum or bourbon, not white. Crumbs as fine as sand. Toasted nuts, chopped fine. Mix until it rolls like play dough. Small balls, the size of a walnut. Roll them in sugar, cocoa or nuts. And let them rest in a tin for at least three days. That's Aunt Margaret's rum balls, and she'd know if you ate one early.""",
   "rum balls Christmas cookie tray", "SHE'D KNOW")
sc("""Tell me in the comments, sweetheart. Rum balls or bourbon balls? And did your family have a secret grown-up treat on the Christmas tray? The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas cookie tray evening", "RUM OR BOURBON?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma69", "Christmas Rum Balls EVERYONE's Grandma Made (Why Yours Are DRY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Rum balls and bourbon balls, no-bake confections made from cookie crumbs, nuts, cocoa and spirits, common in mid-century American church cookbooks.",
      "Recipe as written by Grandma Ruth: 2 1/2 cups fine vanilla wafer crumbs, 1 cup powdered sugar, 1 cup finely chopped toasted pecans, 2 tbsp cocoa, 3 tbsp corn syrup or honey, 1/2 cup dark rum; rested at least 3 days."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
